USE sekai_friend;

INSERT INTO sekai_word_words (english, chinese, phonetic, example_sentence, category, difficulty)
SELECT english, chinese, phonetic, example_sentence, category, difficulty
FROM (
    SELECT 'abandon' english, '放弃；抛弃；舍弃' chinese, '[uh-BAN-duhn]' phonetic, 'Do not abandon your study plan easily.' example_sentence, 'CET-6 高频核心' category, 'medium' difficulty
    UNION ALL SELECT 'abstract', '抽象的；摘要；提取', '[AB-strakt]', 'The article begins with an abstract idea.', 'CET-6 阅读核心', 'hard'
    UNION ALL SELECT 'abundant', '丰富的；充足的', '[uh-BUN-duhnt]', 'The region has abundant natural resources.', 'CET-6 高频核心', 'medium'
    UNION ALL SELECT 'academic', '学术的；学院的', '[ak-uh-DEM-ik]', 'Academic writing requires clear evidence.', 'CET-6 学术科技', 'medium'
    UNION ALL SELECT 'accelerate', '加速；促进', '[ak-SEL-uh-rayt]', 'Technology can accelerate social change.', 'CET-6 学术科技', 'hard'
    UNION ALL SELECT 'access', '接近；进入；使用权', '[AK-ses]', 'Students need access to reliable information.', 'CET-6 学术科技', 'medium'
    UNION ALL SELECT 'accommodate', '容纳；适应；提供住宿', '[uh-KOM-uh-dayt]', 'The hall can accommodate two hundred people.', 'CET-6 高频核心', 'hard'
