    UNION ALL SELECT 'adequate', '足够的；适当的', '[AD-i-kwit]', 'Adequate sleep improves concentration.', 'CET-6 写作表达', 'medium'
    UNION ALL SELECT 'adjacent', '邻近的；毗连的', '[uh-JAY-suhnt]', 'The school is adjacent to a public library.', 'CET-6 阅读核心', 'medium'
    UNION ALL SELECT 'advocate', '提倡；拥护者', '[AD-vuh-kayt]', 'Many experts advocate lifelong learning.', 'CET-6 写作表达', 'hard'
    UNION ALL SELECT 'affection', '喜爱；感情', '[uh-FEK-shuhn]', 'The story expresses deep affection for family.', 'CET-6 阅读核心', 'medium'
    UNION ALL SELECT 'agenda', '议程；待办事项', '[uh-JEN-duh]', 'Environmental protection is high on the agenda.', 'CET-6 社会经济', 'medium'
    UNION ALL SELECT 'allocate', '分配；拨出', '[AL-uh-kayt]', 'The government will allocate more funds to education.', 'CET-6 社会经济', 'hard'
    UNION ALL SELECT 'alternative', '可替代的；替代方案', '[awl-TUR-nuh-tiv]', 'Online courses offer an alternative way to learn.', 'CET-6 高频核心', 'medium'
    UNION ALL SELECT 'ambiguous', '模棱两可的；含糊的', '[am-BIG-yoo-uhs]', 'The instruction is ambiguous and confusing.', 'CET-6 阅读核心', 'hard'
    UNION ALL SELECT 'amplify', '放大；增强；详述', '[AM-pluh-fy]', 'Examples can amplify the main argument.', 'CET-6 写作表达', 'hard'
    UNION ALL SELECT 'anticipate', '预期；期待；预见', '[an-TIS-uh-payt]', 'We anticipate further growth next year.', 'CET-6 高频核心', 'hard'
