    UNION ALL SELECT 'deficiency', '缺乏；不足；缺陷', '[di-FISH-uhn-see]', 'A vitamin deficiency can harm health.', 'CET-6 学术科技', 'hard'
    UNION ALL SELECT 'demonstrate', '证明；展示；示威', '[DEM-uhn-strayt]', 'The experiment demonstrates the principle.', 'CET-6 学术科技', 'medium'
    UNION ALL SELECT 'derive', '获得；源于；推导出', '[di-RYV]', 'Many English words derive from Latin.', 'CET-6 阅读核心', 'hard'
    UNION ALL SELECT 'dimension', '方面；维度；尺寸', '[di-MEN-shuhn]', 'The issue has an economic dimension.', 'CET-6 阅读核心', 'medium'
