    UNION ALL SELECT 'duration', '持续时间；期间', '[doo-RAY-shuhn]', 'The duration of the course is twelve weeks.', 'CET-6 学术科技', 'medium'
    UNION ALL SELECT 'eliminate', '消除；淘汰', '[i-LIM-uh-nayt]', 'The new rule aims to eliminate waste.', 'CET-6 高频核心', 'medium'
