    UNION ALL SELECT 'enhance', '提高；增强；改善', '[en-HANS]', 'Reading can enhance vocabulary.', 'CET-6 高频核心', 'medium'
    UNION ALL SELECT 'equivalent', '相等的；等同物', '[i-KWIV-uh-luhnt]', 'This test is equivalent to a final exam.', 'CET-6 阅读核心', 'hard'
    UNION ALL SELECT 'evaluate', '评价；评估', '[i-VAL-yoo-ayt]', 'We need to evaluate the results carefully.', 'CET-6 学术科技', 'medium'
