    UNION ALL SELECT 'expand', '扩大；扩展；膨胀', '[ik-SPAND]', 'The company plans to expand overseas.', 'CET-6 社会经济', 'medium'
    UNION ALL SELECT 'explicit', '明确的；清楚的', '[ik-SPLIS-it]', 'The teacher gave explicit instructions.', 'CET-6 阅读核心', 'hard'
    UNION ALL SELECT 'facilitate', '促进；使便利', '[fuh-SIL-i-tayt]', 'Good tools facilitate independent learning.', 'CET-6 学术科技', 'hard'
    UNION ALL SELECT 'fluctuate', '波动；起伏', '[FLUK-choo-ayt]', 'Prices fluctuate with demand.', 'CET-6 社会经济', 'hard'
    UNION ALL SELECT 'fundamental', '基本的；根本的', '[fun-duh-MEN-tuhl]', 'Trust is fundamental to cooperation.', 'CET-6 高频核心', 'medium'
    UNION ALL SELECT 'hypothesis', '假设；假说', '[hy-POTH-uh-sis]', 'The data support the hypothesis.', 'CET-6 学术科技', 'hard'
    UNION ALL SELECT 'implement', '实施；工具', '[IM-pluh-ment]', 'The school will implement a new policy.', 'CET-6 社会经济', 'hard'
    UNION ALL SELECT 'implicit', '含蓄的；暗含的', '[im-PLIS-it]', 'The message is implicit rather than direct.', 'CET-6 阅读核心', 'hard'
    UNION ALL SELECT 'incentive', '激励；刺激；诱因', '[in-SEN-tiv]', 'Scholarships provide an incentive to study.', 'CET-6 社会经济', 'hard'
    UNION ALL SELECT 'inevitable', '不可避免的', '[in-EV-i-tuh-buhl]', 'Change is inevitable in modern life.', 'CET-6 写作表达', 'hard'
    UNION ALL SELECT 'infrastructure', '基础设施', '[IN-fruh-struk-cher]', 'The city needs better infrastructure.', 'CET-6 社会经济', 'hard'
    UNION ALL SELECT 'initiative', '主动性；倡议；新方案', '[i-NISH-uh-tiv]', 'Students should take the initiative in learning.', 'CET-6 写作表达', 'hard'
    UNION ALL SELECT 'innovation', '创新；革新', '[in-uh-VAY-shuhn]', 'Innovation drives economic growth.', 'CET-6 学术科技', 'medium'
    UNION ALL SELECT 'integrate', '整合；结合；融入', '[IN-ti-grayt]', 'The system integrates practice and review.', 'CET-6 学术科技', 'hard'
