    UNION ALL SELECT 'prospect', '前景；可能性；景象', '[PROS-pekt]', 'Job prospects are improving.', 'CET-6 社会经济', 'medium'
    UNION ALL SELECT 'random', '随机的；任意的', '[RAN-duhm]', 'The system selects words in random order.', 'CET-6 学术科技', 'easy'
    UNION ALL SELECT 'reform', '改革；改良', '[ri-FORM]', 'Education reform requires patience.', 'CET-6 社会经济', 'medium'
